/**
 *
 * DataTableFooter renders an optional footer slot below the DataTable's table container.
 *
 * [Live Demo](https://www.primereact.org/datatable/)
 *
 * @module DataTableFooter
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { DataTableRootInstance } from './DataTableRoot.types';
/**
 * Defines passthrough(pt) options type in DataTableFooter component.
 */
export type DataTableFooterPassThroughType<E> = PassThroughType<DataTableFooterInstance, E>;
/**
 * Defines passthrough(pt) options of DataTableFooter component.
 */
export interface DataTableFooterPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: DataTableFooterPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
}
/**
 * Defines valid properties in DataTableFooter component.
 */
export interface DataTableFooterProps extends BaseComponentProps<DataTableFooterInstance, unknown, DataTableFooterPassThrough> {
}
/**
 * Defines valid state in DataTableFooter component.
 */
export interface DataTableFooterState {
}
/**
 * Defines the methods and properties exposed by DataTableFooter component.
 */
export interface DataTableFooterExposes {
    /**
     * The DataTable component instance.
     */
    datatable: DataTableRootInstance | undefined | null;
}
/**
 * Instance of DataTableFooter component.
 */
export type DataTableFooterInstance = ComponentInstance<DataTableFooterProps, DataTableFooterState, DataTableFooterExposes>;
